# Code generated by Claude
"""
Tests of "the neck frames once, then holds" (the eagle camera is a policy input: no following, no operator override while recording).

    MUJOCO_GL=egl python experiments/neck_once_test.py

1. The framing solve is repeatable: at the handoff pose (the staging pose, arms at home; the staging's own framing points) the solve is bit-identical when repeated, and moves
   by less than 0.06 rad when the arms, the base and the beaker are perturbed by 0.1 degree, 0.2 mm and 0.5 mm (the old solver moved lift and elbow by about 1 rad).
2. neck_auto (src/neck_source.py), driven with scripted observations (no stepping): drive -> the drive pose once; at rest -> ONE framing after resume_delay,
   then nothing (hold); drive again and stop -> one more. With specs follow=True but recording=True it still holds; with follow=True and no recording it follows.
   Inactive (teleop off) it does nothing. The task points are used when the scene has a task (F7's points), the hands' points otherwise.
3. The keyboard source (src/keyboard_source.py): neck keys work normally; with neck_locked=True they give no command, one notice line per key press,
   and the other keys (here: the pedestal) still work.
4. The staging NECK stage: one frame_points call per episode; after a hand-back (restore_step) the stored targets are sent again with no new solve.
"""

import contextlib
import io
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import neck_framing, neck_source, robot_specs, staging_source  # noqa: E402
from src.keyboard_source import DRIVE_CFG, key_code, make_keyboard_source  # noqa: E402
from neck_framing_test import place_handoff  # noqa: E402
from src.task_beaker_hotplate import framing_points, load_task, spawn_and_settle  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}" + (f"  {detail}" if detail else ""))


class CountedSolve:
    """Wraps neck_framing.frame_points where a module imported it, counting the calls."""

    def __init__(self, module):
        self.module, self.calls, self.orig = module, 0, module.frame_points

    def __enter__(self):
        def wrapped(*a, **k):
            self.calls += 1
            return self.orig(*a, **k)
        self.module.frame_points = wrapped
        return self

    def __exit__(self, *exc):
        self.module.frame_points = self.orig


def drive_rest_script(src, rest1=(1.0, 4.0), drive=(0.0, 1.0), drive2=(5.0, 6.0), rest2=(6.0, 9.0), neck_goal=None):
    """Feeds the source ticks of 0.1 s: driving in `drive` and `drive2`, at rest otherwise, up to rest2's end. Returns the list of (t, command)."""
    out = []
    n = int(round(rest2[1] * 10))
    for k in range(n):
        t = round(k * 0.1, 3)
        driving = drive[0] <= t < drive[1] or drive2[0] <= t < drive2[1]
        obs = {"time": t, "applied": {"twist": (0.5, 0.0) if driving else (0.0, 0.0), "neck_goal": neck_goal}}
        for c in src["step"](obs):
            out.append((t, c))
    return out


def main():
    with contextlib.redirect_stdout(io.StringIO()):
        sim = load_task(cameras=True)
    model, data = sim.model, sim.data
    spawn_and_settle(sim)
    place_handoff(sim)                       # the staging pose, both arms at home, the neck at the drive pose: what the staging NECK stage frames
    mujoco.mj_kinematics(model, data)
    NS = robot_specs.NECK_SPECS
    goal = dict(zip(NS["active_joints"], NS["drive_pose"]))
    points = framing_points(model, data)
    teleop_on, teleop_off = {"state": {"on": True}}, {"state": {"on": False}}
    kb_state = {"state": {"neck_active_t": -1e9}}

    print("1. the solve is repeatable")
    t1, _ = neck_framing.frame_points(model, data, points)
    t2, _ = neck_framing.frame_points(model, data, points)
    check("the same points give bit-identical targets", all(t1[n] == t2[n] for n in t1), f"{ {n: round(v, 4) for n, v in t1.items()} }")
    rng = np.random.default_rng(1)
    q0 = data.qpos.copy()
    worst = 0.0
    for _ in range(4):
        data.qpos[:] = q0
        for sd in ("left", "right"):
            for i in range(1, 8):
                data.qpos[model.joint(f"openarm_{sd}_joint{i}").qposadr[0]] += 1.7e-3 * rng.standard_normal()
        mujoco.mj_kinematics(model, data)
        tp, _ = neck_framing.frame_points(model, data, framing_points(model, data))
        worst = max(worst, max(abs(tp[n] - t1[n]) for n in t1))
    data.qpos[:] = q0
    mujoco.mj_kinematics(model, data)
    check("0.1 degree of noise on every arm joint moves no neck joint by more than 0.06 rad", worst < 0.06, f"largest change {worst:.3f} rad")

    print("2. neck_auto: look ahead while driving, one framing per stop, then hold")
    with CountedSolve(neck_source) as cnt:
        src = neck_source.make_neck_auto_source(model, data, teleop_on, kb_state, points_fn=framing_points)
        cmds = drive_rest_script(src, neck_goal=goal)
    drive_cmds = [t for t, c in cmds if c["neck_targets"] == goal]
    frame_cmds = [t for t, c in cmds if c["neck_targets"] != goal]
    check("the drive pose is sent once per drive (t=0 and t=5)", drive_cmds == [0.0, 5.0], f"{drive_cmds}")
    check("one framing per stop, after resume_delay (t=2.0 and t=7.0), nothing in between", frame_cmds == [2.0, 7.0], f"{frame_cmds}")
    check("exactly one solve per framing", cnt.calls == 2, f"{cnt.calls} solves")
    check("the two framings are identical (nothing moved)", [c["neck_targets"] for t, c in cmds if t == 2.0] == [c["neck_targets"] for t, c in cmds if t == 7.0])
    check("the task points were framed (the report lists the beaker and hotplate corners)",
          any(k.startswith("beaker_corner") for k in src["state"]["last_report"]["points"]))
    with CountedSolve(neck_source) as cnt:
        src = neck_source.make_neck_auto_source(model, data, teleop_on, kb_state, points_fn=None)
        drive_rest_script(src, neck_goal=goal)
    check("no points_fn: the hands' points are framed", set(src["state"]["last_report"]["points"]) == {"left_tcp", "left_hand", "right_tcp", "right_hand"})
    specs_follow = {**robot_specs.NECK_AUTO_SPECS, "follow": True}
    with CountedSolve(neck_source) as cnt:
        src = neck_source.make_neck_auto_source(model, data, teleop_on, kb_state, specs=specs_follow, points_fn=framing_points, recording=True)
        cmds = drive_rest_script(src, neck_goal=goal)
    check("follow=True while recording: still one solve per stop, no following", cnt.calls == 2, f"{cnt.calls} solves")
    with CountedSolve(neck_source) as cnt:
        src = neck_source.make_neck_auto_source(model, data, teleop_on, kb_state, specs=specs_follow, points_fn=framing_points, recording=False)
        cmds = drive_rest_script(src, neck_goal=goal)
    check("follow=True, not recording: it follows (a solve every 0.5 s of rest)", cnt.calls >= 8, f"{cnt.calls} solves")
    with CountedSolve(neck_source) as cnt:
        src = neck_source.make_neck_auto_source(model, data, teleop_off, kb_state, points_fn=framing_points)
        cmds = drive_rest_script(src, neck_goal=goal)
    check("teleop off: it does nothing", not cmds and cnt.calls == 0)

    print("3. the operator's neck keys")
    down = set()
    held = lambda code: code in down
    ped = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, robot_specs.PEDESTAL_SPECS["actuator_name"])
    ped_range = tuple(model.actuator_ctrlrange[ped])
    keyobs = {"time": 0.0, "timestep": model.opt.timestep, "steps_per_frame": 5,
              "applied": {"pedestal": 0.0, "arm_targets": {"left": np.zeros(7), "right": np.zeros(7)}, "gripper": {"left": 0.04, "right": 0.04}, "neck_goal": goal}}
    for locked in (False, True):
        kb = make_keyboard_source(model, held, DRIVE_CFG, 0.001, ped_range, data=data, neck_specs=NS, points_fn=framing_points, neck_locked=locked)
        notices, neck_cmds = [], []
        for keys in ([], ["9"], ["9"], [], ["F7"], ["F8"], []):
            down.clear()
            down.update(key_code(k) for k in keys)
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                out = kb["step"](keyobs)
            notices += [l for l in buf.getvalue().splitlines() if "disabled" in l]
            neck_cmds += [c for c in out if c["mode"] == "neck"]
        if locked:
            check("locked: neck keys (jog, F7, F8) give no command", not neck_cmds)
            check("locked: one notice line per key press (9 held for two ticks, then F7, then F8: 3 presses)", len(notices) == 3, f"{len(notices)} lines: {notices[:1]}")
        else:
            check("unlocked: jog, F7 and F8 each give a neck command", len(neck_cmds) == 4, f"{len(neck_cmds)} commands")
            check("unlocked: no notice", not notices)
    kb = make_keyboard_source(model, held, DRIVE_CFG, 0.001, ped_range, data=data, neck_specs=NS, neck_locked=True)
    down.clear()
    down.add(key_code("PAGE_UP"))
    out = kb["step"](keyobs)
    check("locked: the other keys still work (Page Up raises the pedestal)", any(c["mode"] == "pedestal" for c in out))

    print("4. the staging NECK stage: one solve per episode; a hand-back re-sends the stored targets")
    from src.episode_runner import run_episode
    from src.task_beaker_hotplate import make_task
    from src.task_config import TASK_CFG
    task = make_task(None)
    captured = {}
    make_policy = task["make_policy"]
    task["make_policy"] = lambda m, d: captured.setdefault("policy", make_policy(m, d))
    with CountedSolve(staging_source) as cnt, contextlib.redirect_stdout(io.StringIO()):
        summary = run_episode(task, model, data, stop_after_handoff_s=0.5)
    check("the episode reached the handoff (STAGING_COMPLETE)", summary["outcome"] == "STAGING_COMPLETE", summary["outcome"])
    check("one framing solve in the whole staging", cnt.calls == 1, f"{cnt.calls} solves")
    stage = captured["policy"]["stages"][0]
    stored = summary["neck_framing_report"]["neck_targets"]
    pq = TASK_CFG["pedestal_q"]
    obs = {"applied": {"pedestal": pq}, "pedestal_height": pq, "joint_velocities": np.zeros(model.nv), "joint_angles": data.qpos}
    with CountedSolve(staging_source) as cnt2:
        sent = []                                        # the restore waits for the pedestal to settle first, then sends the neck targets, then waits for the neck
        for k in range(60):
            cmds, finished = stage["restore_step"](obs, 100.0 + 0.1 * k, 1 / 150)
            sent += cmds
            if finished:
                break
        check("after a hand-back the stored neck targets are sent again, once", len(sent) == 1 and sent[0]["mode"] == "neck" and sent[0]["neck_targets"] == stored, f"{sent}")
        check("the restore finishes once the neck is there", finished)
        check("no new solve during the restore", cnt2.calls == 0, f"{cnt2.calls} solves")

    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
